-- OLIST E-COMMERCE ANALYTICS
-- Intermediate SQL queries | Q06-Q11
-- Database: olist_ecommerce
-- Revenue convention: delivered orders only; item price excludes freight.

USE olist_ecommerce;


-- Q06: Total item revenue and freight generated by delivered orders.
SELECT
    SUM(oi.price) AS total_revenue,
    SUM(oi.freight_value) AS total_freight
FROM orders o
JOIN order_items oi
    ON o.order_id = oi.order_id
WHERE o.order_status = 'delivered';

-- Q06 validation: payments received for delivered orders.
-- This may differ slightly from item revenue + freight due to dataset/payment details.
SELECT
    SUM(p.payment_value) AS total_paid
FROM orders o
JOIN payments p
    ON o.order_id = p.order_id
WHERE o.order_status = 'delivered';


-- Q07: Product categories with the highest number of units sold.
SELECT
    COALESCE(
        t.product_category_name_english,
        NULLIF(p.product_category_name, ''),
        'unknown'
    ) AS category,
    COUNT(*) AS units_sold
FROM order_items oi
JOIN orders o
    ON oi.order_id = o.order_id
JOIN products p
    ON oi.product_id = p.product_id
LEFT JOIN category_translation t
    ON p.product_category_name = t.product_category_name
WHERE o.order_status = 'delivered'
GROUP BY category
ORDER BY units_sold DESC
LIMIT 10;


-- Q08: Top 5 customers by total item spend on delivered orders.
SELECT
    c.customer_unique_id,
    SUM(oi.price) AS total_spent
FROM customers c
JOIN orders o
    ON c.customer_id = o.customer_id
JOIN order_items oi
    ON o.order_id = oi.order_id
WHERE o.order_status = 'delivered'
GROUP BY c.customer_unique_id
ORDER BY total_spent DESC
LIMIT 5;


-- Q09: Sellers who generated more than R$10,000 in delivered item revenue.
SELECT
    s.seller_id,
    s.seller_city,
    SUM(oi.price) AS total_revenue
FROM sellers s
JOIN order_items oi
    ON s.seller_id = oi.seller_id
JOIN orders o
    ON oi.order_id = o.order_id
WHERE o.order_status = 'delivered'
GROUP BY s.seller_id, s.seller_city
HAVING SUM(oi.price) > 10000
ORDER BY total_revenue DESC;


-- Q09 count validation:
-- Same joins, filter, grouping columns and HAVING logic as the seller-level query.
-- Expected count after full source-to-table reconciliation: 282 seller groups.
SELECT
    COUNT(*) AS qualifying_seller_groups
FROM (
    SELECT
        s.seller_id,
        s.seller_city,
        SUM(oi.price) AS total_revenue
    FROM sellers s
    JOIN order_items oi
        ON s.seller_id = oi.seller_id
    JOIN orders o
        ON oi.order_id = o.order_id
    WHERE o.order_status = 'delivered'
    GROUP BY s.seller_id, s.seller_city
    HAVING SUM(oi.price) > 10000
) AS qualifying_sellers;


-- Q10: Average order value by customer city (cities with 50+ delivered orders).
-- AOV here is based on item price only; freight is excluded.
-- First aggregate to one row per order, then calculate the city average.
SELECT
    city,
    ROUND(AVG(order_value), 2) AS avg_order_value,
    COUNT(*) AS orders
FROM (
    SELECT
        c.customer_city AS city,
        o.order_id,
        SUM(oi.price) AS order_value
    FROM customers c
    JOIN orders o
        ON c.customer_id = o.customer_id
    JOIN order_items oi
        ON o.order_id = oi.order_id
    WHERE o.order_status = 'delivered'
    GROUP BY c.customer_city, o.order_id
) AS order_totals
GROUP BY city
HAVING COUNT(*) >= 50
ORDER BY avg_order_value DESC
LIMIT 10;


-- Q11: Number of orders handled and average payment value per payment type.
-- Payment instalments are summed per order/payment type before averaging.
SELECT
    payment_type,
    COUNT(*) AS orders_handled,
    ROUND(AVG(order_payment), 2) AS avg_payment_value
FROM (
    SELECT
        p.order_id,
        p.payment_type,
        SUM(p.payment_value) AS order_payment
    FROM payments p
    JOIN orders o
        ON p.order_id = o.order_id
    WHERE o.order_status = 'delivered'
    GROUP BY p.order_id, p.payment_type
) AS payment_summary
GROUP BY payment_type
ORDER BY orders_handled DESC;
